package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch113 {
    val stories = listOf(
        StorySeries(
            id = "the_last_light_in_the_planetarium",
            title = "The Last Light in the Planetarium",
            tagline = "A student team helps a small planetarium reopen by documenting its exhibits and welcoming new learners.",
            parts = listOf(
                StoryPart(1, "A Quiet Dome", listOf("The town planetarium had been closed for months while its projector and ceiling controls were inspected. When it reopened for a limited school visit, the dome looked unfamiliar without its usual stars.", "Tomi, a member of the science club, noticed that the visitor guide still described equipment that had been replaced.", "The planetarium educator invited the club to help prepare a new guide, with every technical detail checked by staff.")),
                StoryPart(2, "The Old Star Chart", listOf("In a cabinet, Tomi found a star chart drawn by a former educator. It showed constellations visible in different seasons and included handwritten notes about local school visits.", "The chart was beautiful, but some labels used outdated terminology. Tomi asked whether they could preserve the original while creating a modern companion version.", "The educator agreed. The original would remain part of the archive, and the new guide would explain which information had been updated.")),
                StoryPart(3, "Learning the Controls", listOf("The staff member showed the students the visitor-safe controls and explained which switches were restricted to trained operators.", "Tomi wrote a glossary for words such as horizon, constellation, and orbit. His teammate Sade added diagrams that could be understood without operating any equipment.", "They checked each description against the educator's approved reference material.")),
                StoryPart(4, "A Question Without an Easy Answer", listOf("During a practice visit, a younger student asked why a star seemed to move across the sky during the evening.", "Tomi began to describe the movement, then paused when he realised he was mixing up the apparent motion of the sky with the motion of the planet.", "The educator helped him correct the explanation. The team added a question-and-answer page that separated what observers see from what causes it.")),
                StoryPart(5, "The Flickering Display", listOf("A section of the dome display flickered during a staff test. The students stepped back while the operator followed the planetarium's maintenance procedure.", "The visit was paused, and the staff recorded the issue for the technician. No student attempted to repair or adjust the equipment.", "Tomi added a note to the visitor plan explaining that a session could be postponed when a technical check was needed.")),
                StoryPart(6, "A Night of Practice", listOf("The club rehearsed a short presentation using printed star maps rather than the projector. Each student took one topic and practised answering questions clearly.", "Sade noticed that the first draft assumed every visitor already knew the names of the constellations. She suggested beginning with the idea that stars form patterns people have named in different cultures.", "The revised talk made room for curiosity without pretending that every culture sees the same pictures in the sky.")),
                StoryPart(7, "The First Visitors", listOf("On reopening day, families arrived for the first public session. The educator welcomed them and explained that the presentation would use the updated guide.", "Tomi showed visitors the seasonal chart and invited them to compare it with the current sky map. A child spotted a label that needed a larger font.", "The team wrote down the suggestion and thanked the child for helping improve the display.")),
                StoryPart(8, "A Sky of Many Stories", listOf("After the science presentation, the educator invited visitors to share stories and names they had heard for the stars. The group listened respectfully and recorded only contributions people agreed could be included.", "The students learned that astronomy can be studied through careful observation while the history of star stories can also be explored as culture and storytelling.", "They created separate sections in the guide so readers could understand the difference between scientific explanations and traditional narratives.")),
                StoryPart(9, "The Power Returns", listOf("A technician completed the inspection and the projector passed its checks. The planetarium scheduled a new session, and the students helped staff prepare the room for visitors.", "The dome filled with stars again. Tomi watched the audience look upward, then glanced at the new guide on each seat.", "The last light in the room was the small reading lamp at the educator's desk, where the next group of questions was already waiting.")),
                StoryPart(10, "A Place to Keep Looking", listOf("The planetarium reopened with a monthly student session and a feedback book near the entrance. The science club agreed to review the guide each term with the educator.", "Tomi donated a copy of the updated star chart while the original remained safely preserved in the archive.", "As the visitors left, a younger student asked when the next session would be. Tomi pointed to the calendar. The dome was no longer quiet, and its next story had already begun."))
            )
        )
    )
}
